import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Mail, CheckCircle2, AlertCircle, RefreshCw, LogOut } from 'lucide-react';
import { useApp } from '../context/AppContext';
import { apiResendVerificationEmail, apiLogout } from '../services/api';
import { C, BtnOrange } from '../components/UI';

export default function VerifyEmailScreen() {
  const navigate = useNavigate();
  const { user, setUser, checkVerificationStatus } = useApp();
  const [resending, setResending] = useState(false);
  const [checking, setChecking] = useState(false);
  const [countdown, setCountdown] = useState(0);
  const [toast, setToast] = useState(null); // { type: 'success'|'error', msg }

  // Load initial cooldown from localStorage
  useEffect(() => {
    if (user?.email) {
      const lastSent = localStorage.getItem(`nb_cooldown_${user.email}`);
      if (lastSent) {
        const elapsed = Math.floor((Date.now() - parseInt(lastSent, 10)) / 1000);
        if (elapsed < 60) {
          setCountdown(60 - elapsed);
        }
      }
    }
  }, [user]);

  // Check verification on mount just in case
  useEffect(() => {
    let active = true;
    async function quickCheck() {
      const verified = await checkVerificationStatus();
      if (verified && active) {
        navigate('/home');
      }
    }
    quickCheck();
    return () => { active = false; };
  }, []);

  // Handle Resend Countdown
  useEffect(() => {
    if (countdown > 0) {
      const timer = setTimeout(() => setCountdown(c => c - 1), 1000);
      return () => clearTimeout(timer);
    }
  }, [countdown]);

  async function handleCheckVerified() {
    setChecking(true);
    setToast(null);
    try {
      const verified = await checkVerificationStatus();
      if (verified) {
        setToast({ type: 'success', msg: 'Email successfully verified! Redirecting...' });
        setTimeout(() => navigate('/home'), 1200);
      } else {
        setToast({ type: 'error', msg: 'Email is not verified yet. Please click the link in your inbox.' });
      }
    } catch (err) {
      setToast({ type: 'error', msg: err.message || 'Verification check failed.' });
    } finally {
      setChecking(false);
    }
  }

  async function handleResend() {
    setResending(true);
    setToast(null);
    try {
      await apiResendVerificationEmail();
      setToast({ type: 'success', msg: 'Verification link successfully resent to your email!' });
      setCountdown(60); // 1-minute throttle
      if (user?.email) {
        localStorage.setItem(`nb_cooldown_${user.email}`, Date.now().toString());
      }
    } catch (err) {
      if (err.code === 'auth/too-many-requests' || err.message?.includes('too-many-requests')) {
        setToast({ 
          type: 'error', 
          msg: 'Too many requests. Please wait a few minutes before requesting another verification email.' 
        });
      } else {
        setToast({ type: 'error', msg: err.message || 'Failed to resend verification email.' });
      }
    } finally {
      setResending(false);
    }
  }

  function handleCancel() {
    apiLogout();
    setUser(null);
    navigate('/onboarding');
  }

  return (
    <div className="phone-frame" style={{ padding: '0 24px', display: 'flex', flexDirection: 'column', background: C.bg, color: C.text }}>
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', textAlign: 'center', paddingBottom: 60 }}>

        {/* Animated Visual Icon */}
        <div style={{ width: 80, height: 80, borderRadius: '50%', background: 'rgba(255,107,53,0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: 24, color: C.orange }}>
          <Mail size={40} className="pulse-icon" />
        </div>

        <h1 style={{ fontSize: 26, fontWeight: 800, color: '#fff', marginBottom: 12 }}>Verify Your Email ✉️</h1>
        <p style={{ color: C.muted, fontSize: 14, lineHeight: 1.6, marginBottom: 10, padding: '0 10px' }}>
          We have sent a verification link to:
        </p>
        <div style={{ background: '#1e1e1e', border: `1px solid ${C.border}`, borderRadius: 10, padding: '10px 16px', fontSize: 14, fontWeight: 700, color: C.orange, marginBottom: 24 }}>
          {user?.email || 'your.email@example.com'}
        </div>
        <p style={{ color: C.muted2, fontSize: 12, lineHeight: 1.5, marginBottom: 32, padding: '0 14px' }}>
          Please click the verification link in the email to activate your account. If you do not see it, check your spam folder.
        </p>

        {/* Toast Feedbacks */}
        {toast && (
          <div style={{
            display: 'flex', alignItems: 'center', gap: 10, width: '100%',
            padding: '12px 14px', borderRadius: 12, marginBottom: 20, boxSizing: 'border-box',
            background: toast.type === 'success' ? 'rgba(34,197,94,0.08)' : 'rgba(255,77,109,0.08)',
            border: `1px solid ${toast.type === 'success' ? 'rgba(34,197,94,0.2)' : 'rgba(255,77,109,0.2)'}`,
            color: toast.type === 'success' ? '#4ade80' : '#ff4d6d',
            fontSize: 12, fontWeight: 500, textAlign: 'left'
          }}>
            {toast.type === 'success' ? <CheckCircle2 size={16} style={{ flexShrink: 0 }} /> : <AlertCircle size={16} style={{ flexShrink: 0 }} />}
            <span style={{ flex: 1 }}>{toast.msg}</span>
          </div>
        )}

        {/* Action Triggers */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12, width: '100%' }}>
          <BtnOrange onClick={handleCheckVerified} disabled={checking}>
            {checking ? (
              <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
                <RefreshCw size={15} className="spin-icon" /> Checking...
              </span>
            ) : (
              'I have verified my email'
            )}
          </BtnOrange>

          <button 
            onClick={handleResend}
            disabled={resending || countdown > 0}
            style={{
              width: '100%', padding: '13px', borderRadius: 12,
              background: '#1e1e1e', border: `1.5px solid ${C.border}`,
              color: countdown > 0 ? C.muted2 : '#fff', fontSize: 14, fontWeight: 700,
              cursor: resending || countdown > 0 ? 'not-allowed' : 'pointer',
              transition: 'background 0.2s', display: 'flex', alignItems: 'center', justifyContent: 'center'
            }}
          >
            {countdown > 0 ? `Resend Link in ${countdown}s` : 'Resend Verification Link'}
          </button>

          <button 
            onClick={handleCancel}
            style={{
              width: '100%', padding: '13px', borderRadius: 12,
              background: 'transparent', border: 'none',
              color: '#ff4d6d', fontSize: 14, fontWeight: 700,
              cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6,
              marginTop: 10
            }}
          >
            <LogOut size={15} /> Cancel / Sign Out
          </button>
        </div>

      </div>
    </div>
  );
}
